mapper.select:
SELECT COUNT(*) > 0
FROM tb_complaint_category
WHERE complaint_master_id = #{complaintMasterId}
  AND category_code       = #{categoryCode}
  AND delete_yn           = 'N'

  AND category_id != #{excludeId}

mapper.update:
UPDATE tb_complaint_category SET
  category_name=#{categoryName},
  description=#{description},
  sort_order=#{sortOrder},
  updated_by=#{updatedBy}, updated_ip=#{updatedIp}, updated_at=#{updatedAt}
WHERE category_id = #{categoryId}
